#[test]
fn public_flat_unannotated_primitive_local_sequences_emit_check_results() {
    for source in [
        "pub fn copy_chain() -> I8 {\n    let source = 127\n    let first = source\n    let second = first\n    let copied = second\n    copied\n}\n",
        "pub fn copy_source_tail() -> I32 {\n    let source = 42\n    let copied = source\n    source\n}\n",
        "pub fn earlier_tail() -> I8 {\n    let earlier = 42\n    let later = 7\n    earlier\n}\n",
        "pub fn computed() -> I32 {\n    let source = 1\n    let copied = source + 1\n    copied\n}\n",
        "pub fn var_computed() -> I32 {\n    var source = 1\n    let copied = source + 1\n    copied\n}\n",
        "pub fn compare() -> Bool {\n    let inferred = 1\n    let result = inferred < 2\n    result\n}\n",
        "pub fn copy() -> I32 {\n    let source: I32 = 42\n    var copied = 0\n    copied += source\n    copied\n}\n",
        "pub fn copy_var_source() -> I32 {\n    var source: I32 = 42\n    var copied = 0\n    copied += source\n    copied\n}\n",
        "pub fn div_unresolved_local(left: I32) -> I32 {\n    let one = 1\n    let result = one / left\n    result\n}\n",
        "pub fn mul(left: I32, right: I32) -> I32 {\n    let one = 1\n    let result = one * left\n    result\n}\n",
        "pub fn add(left: I32, right: I32) -> I32 {\n    let one = 1\n    let sum = one + right\n    sum\n}\n",
        "pub fn add_assign(left: I32) -> I32 {\n    var sum = 0\n    sum += left\n    sum\n}\n",
        "pub fn local_assign_op() -> I32 {\nlet first: I32 = 1\nvar second = 2\nsecond += first\nfirst\n}\n",
        "pub fn mutable(left: I32, right: I32) -> I32 {\n    var result = 0\n    result += left\n    result\n}\n",
        "pub fn compare(left: I32) -> Bool {\n    let inferred = 1\n    let result = inferred == left\n    result\n}\n",
        "pub fn remainder_unresolved_local(left: I32) -> I32 {\n    let one = 1\n    let result = one % left\n    result\n}\n",
        "pub fn wrapping_unresolved_local(left: I32) -> I32 {\n    let one = 1\n    let result = one +% left\n    result\n}\n",
        "pub fn remainder_assign_local(left: I32) -> I32 {\n    var result = 0\n    result %= left\n    result\n}\n",
        "pub fn wrapping_assign_local(left: I32) -> I32 {\n    var result = 0\n    result +%= left\n    result\n}\n",
        "pub fn bit_and_unresolved_local(left: I32) -> I32 {\n    let bits = 1\n    let result = bits & left\n    result\n}\n",
        "pub fn bit_or_literal_right() -> I32 {\n    var bits = 1\n    let result = bits | 4\n    result\n}\n",
        "pub fn bit_xor_assign_local(left: I32) -> I32 {\n    var result = 0\n    result ^= left\n    result\n}\n",
        "pub fn add_unresolved_rhs(value: I32) -> I32 {\n    let number = 1\n    let result = value + number\n    result\n}\n",
        "pub fn remainder_unresolved_rhs(value: I32) -> I32 {\n    let number = 1\n    let result = value % number\n    result\n}\n",
        "pub fn wrapping_unresolved_rhs(value: I32) -> I32 {\n    let number = 1\n    let result = value +% number\n    result\n}\n",
        "pub fn bit_and_unresolved_rhs(value: I32) -> I32 {\n    let bits = 1\n    let result = value & bits\n    result\n}\n",
        "pub fn merge_add() -> I32 {\n    var a = 1\n    var b = 2\n    let sum = a + b\n    sum\n}\n",
        "pub fn merge_compare() -> Bool {\n    var a = 1\n    var b = 2\n    a < b\n}\n",
        "pub fn merge_assign() -> I32 {\n    var a = 0\n    var b = 2\n    a += b\n    a\n}\n",
        "pub fn merge_reverse_assign() -> I32 {\n    var a = 0\n    var b = 2\n    a += b\n    b += a\n    a\n}\n",
        "pub fn merge_annotated() -> I8 {\n    var a = 1\n    var b = 2\n    let sum: I8 = a + b\n    sum\n}\n",
        "pub fn merge_bit_or() -> I32 {\n    var a = 1\n    var b = 2\n    let bits = a | b\n    bits\n}\n",
        "pub fn merge_remainder() -> I32 {\n    var a = 9\n    var b = 4\n    let rem = a % b\n    rem\n}\n",
        "pub fn literal_left_rem() -> I32 {\n    var x = 4\n    let rem = 1 % x\n    rem\n}\n",
        "pub fn literal_left_wrap() -> I32 {\n    var x = 2\n    let wrapped = 1 +% x\n    wrapped\n}\n",
        "pub fn literal_left_bit() -> I32 {\n    var x = 3\n    let bits = 1 & x\n    bits\n}\n",
        "pub fn literal_left_wrap_unresolved() -> I32 {\n    let one = 1\n    let result = 1 +% one\n    result\n}\n",
        "pub fn literal_var_shift_left(count: U32) -> I32 {\n    var x = 1\n    let r = x << count\n    r\n}\n",
        "pub fn literal_var_shift_count(value: I32) -> I32 {\n    var c = 4\n    let r = value << c\n    r\n}\n",
        "pub fn literal_var_shift_pair() -> I32 {\n    var x = 1\n    var c = 2\n    let r = x << c\n    r\n}\n",
        "pub fn loop_break() -> I32 {\n    var n: I32 = 0\n    loop { n = n + 1\n break }\n    n\n}\n",
        "pub fn loop_labeled() -> I32 {\n    var n: I32 = 0\n    'outer: loop { loop { break 'outer }\n break }\n    n\n}\n",
        "pub fn break_value_loop() -> I32 {\n    loop { break 1 }\n    0\n}\n",
        "pub fn break_value_if(flag: Bool) -> I32 {\n    loop { break if flag { 1 } else { 2 } }\n    0\n}\n",
        "pub fn break_value_match(value: I32) -> I32 {\n    loop { break match value { 1 => 7, _ => 0 } }\n    0\n}\n",
        "pub fn break_value_byte() -> Byte {\n    loop { break b'a' }\n    b'z'\n}\n",
        "pub fn break_value_char() -> Char {\n    loop { break 'a' }\n    'z'\n}\n",
        "pub fn break_value_loop() -> I32 {\n    loop { break loop { break 1 } }\n    0\n}\n",
        "pub fn break_value_loop_pair(flag: Bool) -> I32 {\n    loop { if flag { break 1 } else { break 2 } }\n    0\n}\n",
        "pub fn break_value_labeled() -> I32 {\n    'outer: loop { loop { break 'outer 5 }\n break 'outer 6 }\n    0\n}\n",
        "pub fn loop_tail_break_value() -> I32 {\n    loop { break 1 }\n}\n",
        "pub fn loop_init_annotated() -> I32 {\n    let x: I32 = loop { break 1 }\n    x\n}\n",
        "pub fn loop_init_unannotated() -> I64 {\n    let x = loop { break 1 }\n    x\n}\n",
        "pub fn while_stmt(flag: Bool) -> I32 {\n    var n: I32 = 0\n    while flag { n = n + 1 }\n    n\n}\n",
        "pub fn while_empty(flag: Bool) -> I32 {\n    while flag { }\n    0\n}\n",
        "pub fn return_stmt() -> I32 {\n    var x = 1\n    return x\n    0\n}\n",
        "pub fn return_in_loop() -> I32 {\n    loop { return 7\n break }\n    0\n}\n",
        "pub fn return_tail() -> I32 {\n    return 5\n}\n",
        "pub fn return_tail_in_if(flag: Bool) -> I32 {\n    if flag { return 1 } else { 2 }\n}\n",
        "pub fn return_tail_in_match(value: I32) -> I32 {\n    match value { 1 => return 5, _ => 0 }\n}\n",
    ] {
        assert_success_result(run_check(source, "", &[], &[]), "wasm32-core", "dev");
    }
}

#[test]
fn flat_unannotated_copy_chain_checks_the_shared_literal_once() {
    let source = "pub fn copy_chain() -> I8 {\n    let source = 128\n    let first = source\n    let second = first\n    let copied = second\n    copied\n}\n";
    let output = run_check(source, "", &[], &[]);
    let stdout = String::from_utf8(output.stdout).expect("CLI stdout is UTF-8");
    let initializer_start = source.find("128").expect("integer initializer exists");

    assert_eq!(output.status.code(), Some(1), "{stdout}");
    assert_eq!(
        stdout.matches("\"code\":\"LITERAL_OUT_OF_RANGE\"").count(),
        1,
        "the shared literal must be range-checked once:\n{stdout}"
    );
    assert!(
        stdout.contains("\"message\":\"integer literal is out of range for `I8`\"")
            && !stdout.contains("\"code\":\"TYPE_MISMATCH\"")
            && !stdout.contains("\"code\":\"FEATURE_NOT_IMPLEMENTED\"")
            && !stdout.contains("\"type\":\"result\""),
        "the I8 tail should constrain the source literal through the copy chain:\n{stdout}"
    );
    assert_json_diagnostic_primary_span(
        &stdout,
        "LITERAL_OUT_OF_RANGE",
        "integer literal is out of range for `I8`",
        initializer_start,
        initializer_start + "128".len(),
    );
}

#[test]
fn flat_unannotated_primitive_locals_preserve_literal_origins_and_spans() {
    let source = "pub fn multiple_literals() -> I8 {\n    let returned = 127\n    let unused = 1e309\n    let copied = returned\n    copied\n}\n";
    let output = run_check(source, "", &[], &[]);
    let stdout = String::from_utf8(output.stdout).expect("CLI stdout is UTF-8");
    let initializer = "1e309";
    let initializer_start = source
        .find(initializer)
        .expect("unused float initializer exists");
    assert_eq!(output.status.code(), Some(1), "{stdout}");
    assert!(
        stdout.matches("\"code\":\"LITERAL_OUT_OF_RANGE\"").count() == 1
            && stdout.contains("\"message\":\"floating-point literal is out of range for `F64`\"")
            && !stdout.contains("\"code\":\"TYPE_MISMATCH\"")
            && !stdout.contains("\"code\":\"FEATURE_NOT_IMPLEMENTED\"")
            && !stdout.contains("\"type\":\"result\""),
        "only the unused float's F64 default should fail:\n{stdout}"
    );
    assert_json_diagnostic_primary_span(
        &stdout,
        "LITERAL_OUT_OF_RANGE",
        "floating-point literal is out of range for `F64`",
        initializer_start,
        initializer_start + initializer.len(),
    );

    let source = "pub fn annotation_constrains_literal() -> I8 {\n    let source = 128\n    let narrowed: I8 = source\n    narrowed\n}\n";
    let output = run_check(source, "", &[], &[]);
    let stdout = String::from_utf8(output.stdout).expect("CLI stdout is UTF-8");
    let initializer_start = source.find("128").expect("integer initializer exists");
    assert_eq!(output.status.code(), Some(1), "{stdout}");
    assert!(
        stdout.matches("\"code\":\"LITERAL_OUT_OF_RANGE\"").count() == 1
            && stdout.contains("\"message\":\"integer literal is out of range for `I8`\"")
            && !stdout.contains("\"code\":\"TYPE_MISMATCH\"")
            && !stdout.contains("\"code\":\"FEATURE_NOT_IMPLEMENTED\"")
            && !stdout.contains("\"type\":\"result\""),
        "the annotation should constrain the original integer literal:\n{stdout}"
    );
    assert_json_diagnostic_primary_span(
        &stdout,
        "LITERAL_OUT_OF_RANGE",
        "integer literal is out of range for `I8`",
        initializer_start,
        initializer_start + "128".len(),
    );

    let source = "pub fn incompatible_annotation() -> F32 {\n    let source = 18446744073709551616\n    let floating: F32 = source\n    floating\n}\n";
    let output = run_check(source, "", &[], &[]);
    let stdout = String::from_utf8(output.stdout).expect("CLI stdout is UTF-8");
    let path_start = source
        .rfind("source")
        .expect("annotated source path exists");
    let initializer_start = source
        .find("18446744073709551616")
        .expect("integer initializer exists");
    assert_eq!(output.status.code(), Some(1), "{stdout}");
    assert!(
        stdout.matches("\"code\":\"TYPE_MISMATCH\"").count() == 1
            && stdout.matches("\"code\":\"LITERAL_OUT_OF_RANGE\"").count() == 1
            && stdout.contains("\"message\":\"expected `F32`, found an integer literal\"")
            && stdout.contains("\"message\":\"integer literal is out of range for `I64`\"")
            && !stdout.contains("\"code\":\"FEATURE_NOT_IMPLEMENTED\"")
            && !stdout.contains("\"type\":\"result\""),
        "an incompatible annotation should recover its destination while defaulting the source literal:\n{stdout}"
    );
    assert_json_diagnostic_primary_span(
        &stdout,
        "TYPE_MISMATCH",
        "expected `F32`, found an integer literal",
        path_start,
        path_start + "source".len(),
    );
    assert_json_diagnostic_primary_span(
        &stdout,
        "LITERAL_OUT_OF_RANGE",
        "integer literal is out of range for `I64`",
        initializer_start,
        initializer_start + "18446744073709551616".len(),
    );
}

#[test]
fn unsupported_flat_unannotated_primitive_local_forms_remain_gated() {
    for source in [
        "pub fn self_reference() -> I32 {\n    let source = source\n    source\n}\n",
        "pub fn forward_reference() -> I32 {\n    let copied = later\n    let later = 1\n    copied\n}\n",
        "pub fn raw_path() -> I32 {\n    let source = 1\n    let copied = r#source\n    copied\n}\n",
        "pub fn qualified_path() -> I32 {\n    let source = 1\n    let copied = values.VALUE\n    copied\n}\n",
        "pub fn generic_path() -> I32 {\n    let source = 1\n    let copied = source<I32>\n    copied\n}\n",
    ] {
        assert_check_stays_gated(&run_check(source, "", &[], &[]), source);
    }

    let source = concat!(
        "use acme:empty/values as values\n",
        "pub const LOCAL: I32 = 0\n",
        "pub fn qualified_path() -> I32 {\n",
        "    let source = 1\n",
        "    let copied = values.VALUE\n",
        "    copied\n",
        "}\n",
    );
    assert_success_result(
        run_check(
            source,
            "",
            &[("src/values.sai", "pub const VALUE: I32 = 42\n")],
            &[],
        ),
        "wasm32-core",
        "dev",
    );
}

