#[test]
fn public_unit_return_discards_tail_values() {
    // A tail checked against the implicit or explicit `()` return discards
    // its value (spec 6.11.1/6.25.2).
    for source in [
        "pub fn f() { 1 }\n",
        "pub fn f() -> () { 1 }\n",
        "pub fn f() { if true { 1 } else { 2 } }\n",
        "pub fn f() { if true { 1 } else {} }\n",
        "pub fn f() { if true {} else { 2 } }\n",
        "pub fn f() { if true { 1 } }\n",
        "pub fn f(flag: Bool) { if flag { 1 } else { 2 } }\n",
        "pub fn f(flag: Bool) { if flag { 1 } }\n",
        "pub fn f() { if true { 1 } else if true { 2 } else { 3 } }\n",
        "pub fn f(flag: Bool) { if flag { 1 } else if flag { 2 } else { 3 } }\n",
        "pub fn f(x: I32) { if x < 1 { 1 } else if x < 2 { 2 } else { 3 } }\n",
        "pub fn f(x: I32) { if x < 10 { x } else { 0 } }\n",
        "pub fn f(flag: Bool) { if flag { flag } }\n",
        "pub fn f(x: I32) { if x < 10 { 1 } else { 2 } }\n",
        "pub fn f() { (1, true) }\n",
        "pub fn f() { 1 + 2 }\n",
        "pub fn f() { 1.5 * 2.0 }\n",
        "pub fn f() { 1 < 2 }\n",
        "pub fn f() { true and false }\n",
        "pub fn f() { not true }\n",
        "pub fn f() { -1 }\n",
        "pub fn f() { if true { 1 + 2 } else { 3 } }\n",
        "pub fn f() { [1 + 2, 3] }\n",
        "pub fn f() { ~1 }\n",
        "pub fn f() { b'a' & b'b' }\n",
        "pub fn f() { b'a' << 1 }\n",
        "pub fn f(x: I32) { 1 }\n",
        "pub fn f(x: I32) { (1, true) }\n",
        "pub fn f(x: I32) { (x, 1) }\n",
        "pub fn f(x: I32) { 1 + 2 }\n",
        "pub fn str_param_to_unit(value: Str) -> () { value }\n",
        "pub fn str_param_without_return(value: Str) { value }\n",
        "pub fn f(x: I32, y: I32) { 1 }\n",
        "pub fn f(x: Bool, y: Bool) { if true { 1 } else { 2 } }\n",
        "pub fn f(x: Bool, y: Bool) { if x { 1 } else { 2 } }\n",
        "pub fn f(x: Bool, y: Bool) { if not x { 1 } else { 2 } }\n",
        "pub fn f(x: I32, y: I32) { if x < 10 { 1 } else { 2 } }\n",
        "pub fn f(x: Bool, y: Bool) { if x { 1 } else if y { 2 } else { 3 } }\n",
        "pub fn f(x: Bool, y: Bool, z: Bool) { if x { 1 } else { 2 } }\n",
        "pub fn f(x: Bool, y: Bool) { if x and y { 1 } else { 2 } }\n",
        "pub fn f(x: I32) { x + 1 }\n",
        "pub fn f(x: I32, y: I32) { x + y }\n",
        "pub fn f(x: Bool) { not x }\n",
        "pub fn f(x: I64) { x << 1 }\n",
        "pub fn f(x: F64) { x + 1.5 }\n",
        "pub fn f(x: I32) { x - 1 * 2 }\n",
        "pub fn f(x: I32) { let y = x + 1\ny }\n",
        "pub fn f() { let x = 1\nx }\n",
        "pub fn f(x: I32) { let y = x\nlet z = y + 1\nz }\n",
        "pub fn f(x: Str) { let y = x\ny }\n",
        "pub fn f(x: I32) { x + 1\nx }\n",
        "pub fn f(x: I32) { let y = x\n() }\n",
        "pub fn f(x: I32) { if x < 10 { x + 1 } else { x } }\n",
        "pub fn f(x: I32) { if x < 10 { x + 1 } }\n",
        "pub fn f(x: I32) { if x < 10 { let y = x + 1\ny } else { x * 2 } }\n",
        "pub fn f(x: I32) { if x < 10 { x + 1 } else if x > 20 { x * 2 } else { x } }\n",
        "pub fn f(x: I32) { if x < 10 { x + 1 } else if x > 20 { x * 2 } }\n",
        "pub fn f(x: I32) { if x < 10 { } else { x + 1 } }\n",
        "pub fn f(x: I32) { match x { 0 => if x < 5 { x + 1 } else { x }, _ => x } }\n",
        "pub fn f(x: I32) { match x { 0 => x + 1, _ => x } }\n",
        "pub fn f(x: U8) { match x { 0..=127 => x + 1, 128..=255 => x } }\n",
        "pub fn f() { let x = 1\n() }\n",
        "pub fn f(x: Bool, y: Bool) { if not (x or y) { 1 } else { 2 } }\n",
        "pub fn f(x: I32, y: I32) { if x < y { 1 } else { 2 } }\n",
        "const N: I64 = 1\npub fn f() { N }\n",
        "const N: I64 = 1\npub fn f(x: I32) { N }\n",
        "const N: I64 = 1\npub fn f() { (N, true) }\n",
        "const N: I64 = 1\npub fn f() { if true { N } else { 2 } }\n",
        "const S: Str = \"a\"\npub fn f() { S }\n",
        "const C: I64 = 1\nconst D: I64 = C\npub fn f() { D }\n",
        // Statement-position `if` without `else` checks its branch against
        // `()` (spec 6.14.1), so discarding tails are admitted; the same
        // applies inside `while` bodies and `loop` tails.
        "pub fn f(x: I32) { if x < 10 { x + 1 }\n1 }\n",
        "pub fn f(x: I32) { if x < 10 { let y = x + 1\ny }\n1 }\n",
        "pub fn f(x: I32) { if x < 10 { } else { x + 1 }\n1 }\n",
        "pub fn f(x: I32) { if x < 10 { } else if x > 5 { x + 1 }\n1 }\n",
        "pub fn f(x: I32) { while x < 10 { x + 1 } }\n",
        "pub fn f(x: I32) { while x < 10 { x + 1 }\n1 }\n",
        "pub fn f(x: I32) { while x < 10 { let y = x + 1\ny }\n1 }\n",
        "pub fn f(x: I32) { while x < 10 { if x > 5 { x } else { break } }\n1 }\n",
        "pub fn f(x: I32) { loop { if x < 10 { x + 1 } else { break } }\n1 }\n",
        "pub fn f(x: I32) { loop { if x < 10 { x + 1 } }\n1 }\n",
        "pub fn f(x: I32) { while x < 10 { continue }\n1 }\n",
        // Discarding expression statements synthesize without the return
        // type's expectation, and loop-body `match` tails discard
        // branch-wise.
        "pub fn f() -> Bool { ~1\ntrue }\n",
        "pub fn f() -> Bool { if true { ~1 }\ntrue }\n",
        "pub fn f(x: I32) { loop { match x { 1 => 1, _ => x + 1 } }\n1 }\n",
        "pub fn f(x: I32) { loop { match x { 1 => { x + 1 }, _ => {} } }\n1 }\n",
        "pub fn f(x: I32) -> I32 { x + 1\n0 }\n",
        // A diverging first branch is `Never`-typed, so a plain `else`
        // block needs no unification — it checks like any unit block.
        "pub fn f(x: I32) -> Bool { if x < 10 { return true } else { }\ntrue }\n",
        "pub fn f(x: I32) -> Bool { if x < 10 { return true } else { 5 }\ntrue }\n",
    ] {
        assert_success_result(run_check(source, "", &[], &[]), "wasm32-core", "dev");
    }
}

#[test]
fn public_unit_return_discard_errors_are_diagnosed() {
    for (source, code) in [
        (
            "pub fn f() { 99999999999999999999 }\n",
            "LITERAL_OUT_OF_RANGE",
        ),
        ("pub fn f() { [1, true] }\n", "TYPE_MISMATCH"),
        ("pub fn f() { [] }\n", "TYPE_ANNOTATIONS_NEEDED"),
        (
            "pub fn f() { if true { x } else { 99999999999999999999 } }\n",
            "LITERAL_OUT_OF_RANGE",
        ),
        (
            "pub fn f(flag: Bool) { if flag { [1, true] } else { [1] } }\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub fn f(x: Str, y: I32) { if x < 10 { 1 } else { 2 } }\n",
            "TYPE_MISMATCH",
        ),
        ("pub fn f(x: I32) { x + 1.5 }\n", "TYPE_MISMATCH"),
        ("pub fn f(x: I32) { let y = x + 1.5\ny }\n", "TYPE_MISMATCH"),
        ("pub fn f(x: I32) { let y: I64 = x\ny }\n", "TYPE_MISMATCH"),
        (
            "pub fn f(x: I32) { if x < 10 { x + 1.5 } else { x } }\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub fn f(x: I32) { match x { 0 => x + 1.5, _ => x } }\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub fn f(x: I32) { if x < 10 { x + 1.5 }\n1 }\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub fn f(x: I32) { while x < 10 { x + 1.5 }\n1 }\n",
            "TYPE_MISMATCH",
        ),
        ("pub fn f(x: I32) { while x { 1 }\n1 }\n", "TYPE_MISMATCH"),
        (
            "pub fn f(x: I32) { while x < 10 { break 1 }\n1 }\n",
            "INVALID_BREAK_VALUE",
        ),
        (
            "pub fn f(x: I32) { if x < 10 { 99999999999999999999 }\n1 }\n",
            "LITERAL_OUT_OF_RANGE",
        ),
        (
            "pub fn f(x: I8) { while x < 10 { x + 300 }\n1 }\n",
            "LITERAL_OUT_OF_RANGE",
        ),
    ] {
        let output = run_check(source, "", &[], &[]);
        let stdout = String::from_utf8(output.stdout).expect("CLI stdout is UTF-8");
        assert_eq!(output.status.code(), Some(1), "{stdout}");
        assert!(
            stdout.contains(&format!("\"code\":\"{code}\""))
                && !stdout.contains("\"type\":\"result\"")
                && !stdout.contains("FEATURE_NOT_IMPLEMENTED"),
            "expected {code} without a result or feature gate:\n{stdout}"
        );
    }
}

#[test]
fn public_unit_position_if_branch_tails_discard_values() {
    // Branch tails checked against `()` discard their values (spec
    // 6.11.1/6.25.2), so literal and composite-construction tails in unit
    // positions are valid discards.
    for source in [
        "pub fn f() -> ((), I32) { (if true { 1 } else { 2 }, 3) }\n",
        "pub fn f() -> ((), I32) { (if true { (1, true) } else { (2, false) }, 3) }\n",
        "pub fn f() -> ((), I32) { (if true { () } else { () }, 3) }\n",
    ] {
        assert_success_result(run_check(source, "", &[], &[]), "wasm32-core", "dev");
    }
}

#[test]
fn public_unit_position_direct_elements_do_not_discard() {
    // Direct elements in unit positions are not block tails, so the discard
    // rules do not apply: they report the structural type mismatch.
    let output = run_check("pub fn f() -> ((), I32) { ((1, 2), 3) }\n", "", &[], &[]);
    let stdout = String::from_utf8(output.stdout).expect("CLI stdout is UTF-8");
    assert_eq!(output.status.code(), Some(1), "{stdout}");
    assert!(
        stdout.contains("\"code\":\"TYPE_MISMATCH\"") && !stdout.contains("\"type\":\"result\""),
        "expected TYPE_MISMATCH without a result:\n{stdout}"
    );
}

#[test]
fn public_parameterized_composite_literal_returns_emit_check_result() {
    for source in [
        "pub fn f(x: I32) -> (I32, Bool) { (1, true) }\n",
        "pub fn f(x: I32, y: I32) -> Array<I32, 2> { [1, 2] }\n",
        "const N: I64 = 1\npub fn f() -> (I64, I64) { (N, 1) }\n",
        "const N: I32 = 1\npub fn f() -> Array<I32, 2> { [N, 1] }\n",
        "const S: Str = \"a\"\npub fn f() -> (Str, I64) { (S, 1) }\n",
        "pub fn f(x: I32) -> (I32, I32) { (x + 1, 2) }\n",
        "pub fn f(x: I32) -> Array<I32, 2> { [x + 1, x * 2] }\n",
        "pub fn f(x: I32) -> (Bool, Bool) { (x < 10, x == 5) }\n",
        "pub fn f(x: Bool, y: Bool) -> (Bool, I32) { (x and y, 1) }\n",
        "pub fn f(x: I32) -> (I32, I32) { (-x, x << 2) }\n",
        "pub fn f(x: F64) -> (F64, F64) { (x + 1.5, 2.0) }\n",
        "const N: I32 = 5\npub fn f() -> (I32, I32) { (N + 1, 2) }\n",
        "pub fn f(x: I32) -> (I32, (I32, I32)) { (x, (x + 1, x * 2)) }\n",
        "pub fn f(x: U8) -> (U8, U8) { (x + 1, 200) }\n",
        "pub fn f(x: I32, y: U32) -> (I32, I32) { (x << y, 1) }\n",
        "pub fn f(x: I32) -> (I32, I32) { (x % 3, x +% 2) }\n",
        "pub fn f(x: F32) -> (F32, F32) { (x + 1e38, 1.0) }\n",
    ] {
        assert_success_result(run_check(source, "", &[], &[]), "wasm32-core", "dev");
    }
}

#[test]
fn public_composite_operator_element_errors_are_diagnosed() {
    for (source, code) in [
        (
            "pub fn f(x: I32) -> (I32, I32) { (x + 1.5, 2) }\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub fn f(x: I32) -> (I64, I32) { (x + 1, 2) }\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub fn f(x: F64) -> (F64, F64) { (x + 1, 2.0) }\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub fn f(x: U8) -> (U8, U8) { (x + 300, 2) }\n",
            "LITERAL_OUT_OF_RANGE",
        ),
        (
            "pub fn f(x: I32, y: I32) -> (I32, I32) { (x << y, 1) }\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub fn f(x: I32) -> (I32, I32) { (x << -1, 1) }\n",
            "LITERAL_OUT_OF_RANGE",
        ),
        (
            "pub fn f(x: U8) -> (U8, U8) { (-x, 1) }\n",
            "OPERATOR_NOT_SUPPORTED",
        ),
        (
            "pub fn f(x: F64) -> (F64, F64) { (x % 2.0, 1.0) }\n",
            "OPERATOR_NOT_SUPPORTED",
        ),
        (
            "pub fn f(x: F64) -> (F64, F64) { (x +% 2.0, 1.0) }\n",
            "OPERATOR_NOT_SUPPORTED",
        ),
        (
            "pub fn f(x: F32) -> (F32, F32) { (x + 1e39, 1.0) }\n",
            "LITERAL_OUT_OF_RANGE",
        ),
    ] {
        let output = run_check(source, "", &[], &[]);
        let stdout = String::from_utf8(output.stdout).expect("CLI stdout is UTF-8");
        assert_eq!(output.status.code(), Some(1), "{source:?}:\n{stdout}");
        assert!(
            stdout.contains(&format!("\"code\":\"{code}\""))
                && !stdout.contains("\"type\":\"result\"")
                && !stdout.contains("\"code\":\"FEATURE_NOT_IMPLEMENTED\""),
            "{source:?}: expected {code} without a result or gate:\n{stdout}"
        );
    }
}

