#[test]
fn public_assign_statements_emit_check_results() {
    for source in [
        "pub fn run() -> I32 { var total: I32 = 0\n    total = 1\n    total\n }\n",
        "pub fn run(value: I32) -> I32 { var total: I32 = 0\n    total = value\n    total\n }\n",
        "pub fn run(left: I32, right: I32) -> I32 { var total: I32 = 0\n    total = left + right\n    total\n }\n",
        "pub fn run(flag: Bool, other: Bool) -> Bool { var enabled: Bool = false\n    enabled = flag and other\n    enabled\n }\n",
        "pub fn run(flag: Bool) -> I32 { var total: I32 = 0\n    if flag { total = 1\n    total } else { total = 2\n    total }\n }\n",
        "type Counter { marker: I32 }\nimpl Counter {\n    pub fn run(self: borrow Self) -> I32 {\n        var total: I32 = 0\n        total = self.marker\n        total\n    }\n}\n",
        "pub fn run() -> I32 { var total: I32 = 0\n    total += 1\n    total\n }\n",
        "pub fn run(left: I32, right: I32) -> I32 { var total: I32 = 0\n    total += left\n    total -= right\n    total\n }\n",
        "pub fn run(left: I32) -> I32 { var total: I32 = 1\n    total <<= 4\n    total |= left\n    total\n }\n",
        "pub fn run() -> I32 { var total = 0\n    total = 1\n    total\n }\n",
        "pub fn run(value: I32) -> I32 { var total = 0\n    total = value\n    total\n }\n",
        "pub fn run(var total: I32) -> I32 { total = 1\n    total\n }\n",
        "pub fn run(var total: I32, left: I32) -> I32 { total += left\n    total\n }\n",
    ] {
        assert_success_result(run_check(source, "", &[], &[]), "wasm32-core", "dev");
    }
}

#[test]
fn assign_statement_errors_emit_their_diagnostics() {
    for (source, code) in [
        (
            "pub fn run() -> I32 { let total: I32 = 0\n    total = 1\n    total\n }\n",
            "ASSIGN_TO_IMMUTABLE",
        ),
        (
            "pub fn run(value: I32) -> I32 { value = 1\n    value\n }\n",
            "ASSIGN_TO_IMMUTABLE",
        ),
        (
            "pub fn copy() -> I32 {\n    var source = 42\n    let copied = source\n    copied += 0\n    copied\n}\n",
            "ASSIGN_TO_IMMUTABLE",
        ),
        (
            "pub fn run() -> I32 { var total: I32 = 0\n    total + 1 = 5\n    total\n }\n",
            "INVALID_ASSIGN_TARGET",
        ),
        (
            "pub fn run() -> I32 { var total: I32 = 0\n    total = true\n    total\n }\n",
            "TYPE_MISMATCH",
        ),
    ] {
        let output = run_check(source, "", &[], &[]);
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert!(
            stdout.contains(&format!("\"code\":\"{code}\"")),
            "{code} is reported for:\n{source}\n{stdout}"
        );
    }
}

