#[test]
fn public_flat_tuple_type_errors_suppress_the_check_result() {
    for (source, expected_code) in [
        (
            "pub const FIELD_MISMATCH: (I32, Bool) = (1, 2)\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const FIELD_RANGE: (I8,) = (128,)\n",
            "LITERAL_OUT_OF_RANGE",
        ),
        (
            "pub const ARITY_SHORT: (I32, Bool) = (1,)\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const ARITY_LONG: (I32,) = (1, true)\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const ARITY_EXPRESSIONS: (I32,) = (1 + 2, 3 + 4)\n",
            "TYPE_MISMATCH",
        ),
        ("pub const ARITY_ZERO: (I32,) = ()\n", "TYPE_MISMATCH"),
        ("pub const GROUPED_SCALAR: (I32,) = (1)\n", "TYPE_MISMATCH"),
        (
            "pub const SCALAR_MISMATCH: (I32, Bool) = false\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const UNIT_FIELD_MISMATCH: (I32, ()) = (1, true)\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const FIRST: (I32,) = (1,)\npub const SECOND: (I32,) = (true,)\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const FIELD_OVERFLOW: (I8,) = (127 + 1,)\n",
            "CONST_EVAL_PANIC",
        ),
        (
            "pub const NESTED_OVERFLOW: ((I8,),) = ((127 + 1,),)\n",
            "CONST_EVAL_PANIC",
        ),
        (
            "pub const NESTED_ARITY: ((I32, Bool),) = ((1,),)\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const BASE: I32 = 1\npub const REFERENCE_FOR_TUPLE: ((I32,),) = (BASE,)\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const OPERATOR_FOR_TUPLE: ((I32,),) = (1 + 2,)\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const TUPLE_FOR_SCALAR: (I32,) = ((1,),)\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const ARITY_NESTED_VALUES: (I32,) = ((1,), (2,))\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const FIELD_COMPARISON_MISMATCH: (I32,) = (1 < 2,)\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const TRUTH: Bool = true\npub const FIELD_REFERENCE_MISMATCH: (I32,) = (TRUTH,)\n",
            "TYPE_MISMATCH",
        ),
        (
            "pub const FIRST: (I32,) = (SECOND,)\npub const SECOND: (I32,) = (FIRST,)\n",
            "CONST_CYCLE",
        ),
    ] {
        let output = run_check(source, "", &[], &[]);
        let stdout = String::from_utf8(output.stdout).expect("CLI stdout is UTF-8");
        assert_eq!(
            output.status.code(),
            Some(1),
            "{source:?}: tuple const error should exit 1:\n{stdout}"
        );
        assert!(
            stdout.contains(&format!("\"code\":\"{expected_code}\""))
                && !stdout.contains("\"type\":\"result\"")
                && !stdout.contains("\"code\":\"FEATURE_NOT_IMPLEMENTED\""),
            "{source:?}: expected {expected_code} without a result or feature gate:\n{stdout}"
        );
    }
}

