#[test]
fn nominal_const_constructor_errors_are_checked() {
    for (source, code, message) in [
        (
            concat!(
                "pub type Point { x: I32, y: I32 }\n",
                "pub const ORIGIN: Point = Point(x: 0)\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "MISSING_FIELD",
            "missing fields `y`",
        ),
        (
            concat!(
                "pub type Point { x: I32, y: I32 }\n",
                "pub const ORIGIN: Point = Point(x: 0, z: 1)\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "UNKNOWN_FIELD",
            "unknown record field",
        ),
        (
            concat!(
                "pub type Point { x: I32, y: I32 }\n",
                "pub const ORIGIN: Point = Point(x: 0, y: 1, x: 2)\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "DUPLICATE_FIELD",
            "field is initialized more than once",
        ),
        (
            concat!(
                "pub type Point { x: I32, y: I32 }\n",
                "pub const ORIGIN: Point = Point(x: true, y: 1)\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "TYPE_MISMATCH",
            "expected `I32`, found a Bool literal",
        ),
        (
            concat!(
                "pub type Point { x: I32 }\n",
                "pub const X: I32 = Point(x: 1)\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "TYPE_MISMATCH",
            "expected `I32`, found `Point`",
        ),
        (
            concat!(
                "pub type Point { x: I32 }\n",
                "pub const X: (I32,) = (Point(x: 1),)\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "TYPE_MISMATCH",
            "expected `I32`, found `Point`",
        ),
        (
            concat!(
                "pub type Point { x: I32, y: I32 }\n",
                "pub const CTOR: Point = Point\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "RECORD_CONSTRUCTOR_AS_VALUE",
            "record constructors cannot be used as values",
        ),
        (
            concat!(
                "pub type Point { x: I32, y: I32 }\n",
                "pub const POINT: Point = Point(x: 0, ..POINT)\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "CONST_CYCLE",
            "const depends on itself",
        ),
        (
            concat!(
                "pub enum Status { Ready, Busy(I32) }\n",
                "pub const BUSY: Status = Status.Busy(true)\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "TYPE_MISMATCH",
            "expected `I32`, found a Bool literal",
        ),
        (
            concat!(
                "pub enum Status { Ready, Busy(I32) }\n",
                "pub const BUSY: Status = Status.Busy(1, 2)\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "WRONG_ARGUMENT_COUNT",
            "constructor expects 1 arguments, found 2",
        ),
        (
            concat!(
                "pub enum Status { Ready, Busy(I32) }\n",
                "pub const READY: Status = Status.Ready()\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "WRONG_ARGUMENT_COUNT",
            "unit variant calls do not accept an argument list",
        ),
        (
            concat!(
                "pub enum Status { Ready, Busy(I32) }\n",
                "pub const MISSING: Status = Status.Missing\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "UNKNOWN_VARIANT",
            "unknown enum variant",
        ),
        (
            concat!(
                "pub enum Status { Ready, Busy(I32) }\n",
                "pub const MISSING: Status = Status.Missing(1)\n",
            ),
            "UNKNOWN_VARIANT",
            "unknown enum variant",
        ),
        (
            concat!(
                "pub enum Status { Ready, Busy(I32) }\n",
                "pub const MISSING: Status = .Missing(1)\n",
            ),
            "UNKNOWN_VARIANT",
            "unknown enum variant",
        ),
        (
            concat!(
                "pub enum Status { Ready }\n",
                "pub const MISSING: Status = ._Missing\n",
            ),
            "UNKNOWN_VARIANT",
            "unknown enum variant",
        ),
        (
            concat!(
                "pub enum Status { Ready }\n",
                "pub enum Other { OtherReady }\n",
                "pub const MISSING: Other = Status.Missing(1)\n",
            ),
            "UNKNOWN_VARIANT",
            "unknown enum variant",
        ),
        (
            concat!(
                "type Point { x: I32 }\n",
                "pub const ORIGIN: Point = Point(x: 1)\n",
            ),
            "PRIVATE_TYPE_IN_PUBLIC_API",
            "public const `ORIGIN` uses private type `Point`",
        ),
        (
            concat!(
                "type Point { x: I32 }\n",
                "pub const WRAPPED: (Point,) = (Point(x: 1),)\n",
            ),
            "PRIVATE_TYPE_IN_PUBLIC_API",
            "public const `WRAPPED` uses private type `Point`",
        ),
        (
            concat!(
                "pub enum Status { Ready, Busy(I32) }\n",
                "pub const CTOR: Status = Status.Busy\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "NOT_CONST_EXPRESSION",
            "constructor function items are not constant expressions",
        ),
        (
            concat!(
                "pub distinct UserId = U64\n",
                "pub const ROOT: UserId = UserId(true)\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "TYPE_MISMATCH",
            "expected `U64`, found a Bool literal",
        ),
        (
            concat!(
                "pub distinct UserId = U64\n",
                "pub const ROOT: UserId = UserId(1, 2)\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "WRONG_ARGUMENT_COUNT",
            "constructor expects 1 arguments, found 2",
        ),
        (
            concat!(
                "pub distinct UserId = U64\n",
                "pub const CTOR: UserId = UserId\n",
                "pub fn zero() -> I32 { 0 }\n",
            ),
            "NOT_CONST_EXPRESSION",
            "constructor function items are not constant expressions",
        ),
    ] {
        let output = run_check(source, "", &[], &[]);
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert_eq!(output.status.code(), Some(1), "{stdout}");
        assert!(
            stdout.contains(&format!("\"code\":\"{code}\"")) && stdout.contains(message),
            "expected {code} with {message:?}:\n{stdout}"
        );
        assert!(
            !stdout.contains("\"code\":\"FEATURE_NOT_IMPLEMENTED\""),
            "supported invalid nominal constructor must not be gated:\n{stdout}"
        );
    }
}

#[test]
fn nominal_const_constructor_forms_outside_the_slice_remain_gated() {
    for source in [
        concat!(
            "pub type Boxed<T> { value: T }\n",
            "pub const BOXED: Boxed<I32> = Boxed(value: 1)\n",
            "pub fn zero() -> I32 { 0 }\n",
        ),
        concat!(
            "pub enum Maybe<T> { Some(T) }\n",
            "pub const VALUE: Maybe<I32> = Maybe.Some(1)\n",
            "pub fn zero() -> I32 { 0 }\n",
        ),
        concat!(
            "pub distinct Age = U8\nwhere self <= 150\n",
            "pub const AGE: Age = Age(1)\n",
            "pub fn zero() -> I32 { 0 }\n",
        ),
        concat!(
            "pub enum Recursive { Leaf, Node((Recursive, I32)) }\n",
            "pub const LEAF: Recursive = Recursive.Leaf\n",
        ),
        concat!(
            "pub distinct UserId = Missing\n",
            "pub const ROOT: UserId = UserId(1)\n",
        ),
        concat!(
            "pub enum Duplicated { Ready, Ready }\n",
            "pub const ONE: I32 = 1\n",
        ),
        concat!(
            "pub distinct NegativeArray = Array<I32, -1>\n",
            "pub const ONE: I32 = 1\n",
        ),
        concat!(
            "pub distinct HugeArray = Array<I32, 0x1_0000_0000>\n",
            "pub const ONE: I32 = 1\n",
        ),
        concat!(
            "pub enum Status { Ready }\n",
            "pub const VALUE: Status = Status.make(1)\n",
        ),
    ] {
        let output = run_check(source, "", &[], &[]);
        assert_check_stays_gated(&output, source);
    }
}

