#[test]
fn aggregate_const_reference_errors_are_checked() {
    for (source, message) in [
        (
            "pub const TUPLE_TARGET: (I32,) = (1,)
pub const ARITY_MISMATCH: (I32,) = (TUPLE_TARGET, TUPLE_TARGET)
",
            "expected a tuple with 1 elements, found 2",
        ),
        (
            "pub const POINT: (I32, Bool) = (1, true)
pub const ALIAS: (I32, I32) = POINT
",
            "expected `(I32, I32)`, found `(I32, Bool)`",
        ),
        (
            "pub const VALUES: Array<I32, 2> = [1, 2]
pub const ALIAS: Array<I32, 3> = VALUES
",
            "expected `Array<I32, 3>`, found `Array<I32, 2>`",
        ),
        (
            "pub const POINT: (I32, Bool) = (1, true)
pub const ALIAS: Array<I32, 2> = POINT
",
            "expected `Array<I32, 2>`, found `(I32, Bool)`",
        ),
        (
            "pub const POINT: (I32,) = (1,)
pub const SCALAR_ELEMENT: (I32,) = (POINT,)
",
            "expected `I32`, found `(I32,)`",
        ),
    ] {
        let output = run_check(source, "", &[], &[]);
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert_eq!(output.status.code(), Some(1), "{stdout}");
        assert!(
            stdout.contains("\"code\":\"TYPE_MISMATCH\"") && stdout.contains(message),
            "expected aggregate reference mismatch {message:?}:
{stdout}"
        );
        assert!(
            !stdout.contains("\"code\":\"FEATURE_NOT_IMPLEMENTED\""),
            "supported aggregate reference must not be gated:
{stdout}"
        );
    }
}

#[test]
fn array_const_constructor_errors_are_checked() {
    for (source, code, message) in [
        (
            "pub const SHORT: Array<I32, 2> = [1]\n",
            "ARRAY_LENGTH_MISMATCH",
            "expected array length 2, found 1",
        ),
        (
            "pub const OVERFLOW: Array<I8, 1> = [127 + 1]\n",
            "CONST_EVAL_PANIC",
            "integer overflow in addition",
        ),
        (
            "pub const ELEMENT: Array<I32, 1> = [true]\n",
            "TYPE_MISMATCH",
            "expected `I32`, found a Bool literal",
        ),
        (
            "pub const NESTED_SHORT: Array<Array<I32, 2>, 1> = [[1]]\n",
            "ARRAY_LENGTH_MISMATCH",
            "expected array length 2, found 1",
        ),
        (
            "pub const TUPLE_FOR_ARRAY: Array<I32, 1> = (1,)\n",
            "TYPE_MISMATCH",
            "expected an array, found a tuple",
        ),
        (
            "pub const ARRAY_FOR_TUPLE: (I32,) = [1]\n",
            "TYPE_MISMATCH",
            "expected a tuple, found an array",
        ),
        (
            "pub const ARRAY_FOR_SCALAR: I32 = [1]\n",
            "TYPE_MISMATCH",
            "expected `I32`, found an array",
        ),
        (
            "pub const TUPLE_FOR_SCALAR: I32 = (1,)\n",
            "TYPE_MISMATCH",
            "expected `I32`, found a tuple",
        ),
        (
            "pub const TUPLE_FOR_UNIT: () = (1,)\n",
            "TYPE_MISMATCH",
            "expected `()`, found a tuple",
        ),
        (
            "pub const LOOP: Array<I32, 1> = [LOOP]\n",
            "CONST_CYCLE",
            "const depends on itself",
        ),
    ] {
        let output = run_check(source, "", &[], &[]);
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert_eq!(output.status.code(), Some(1), "{stdout}");
        assert!(
            stdout.contains(&format!("\"code\":\"{code}\"")) && stdout.contains(message),
            "expected {code} with {message:?}:\n{stdout}"
        );
        assert!(
            !stdout.contains("\"code\":\"FEATURE_NOT_IMPLEMENTED\""),
            "supported invalid array constructor must not be gated:\n{stdout}"
        );
    }
}

