#[test]
fn member_const_reference_in_match_scrutinee_checks() {
    // `mod.CONST` member reads type primitive `match` scrutinees in
    // tail, statement, and shared-literal initializer positions.
    let root_source = concat!(
        "use acme:empty/values\n",
        "\n",
        "pub fn tail() -> I32 {\n",
        "    match values.LIMIT {\n",
        "        5 => 1,\n",
        "        _ => 2,\n",
        "    }\n",
        "}\n",
        "pub fn stmt() -> I32 {\n",
        "    match values.LIMIT {\n",
        "        5 => { let x = 1 },\n",
        "        _ => { let x = 2 },\n",
        "    }\n",
        "    0\n",
        "}\n",
        "pub fn joined() -> I32 {\n",
        "    let value = match values.LIMIT {\n",
        "        5 => 1,\n",
        "        _ => 2,\n",
        "    }\n",
        "    value\n",
        "}\n",
    );
    let output = run_check(
        root_source,
        "",
        &[("src/values.sai", "pub const LIMIT: I32 = 5\n")],
        &[],
    );
    assert_success_result(output, "wasm32-core", "dev");
}

#[test]
fn const_patterns_in_primitive_match_check() {
    // Upper-case const paths are value patterns, not bindings. Direct
    // constants and literal-or alternatives type primitive match arms in
    // tail and statement positions; because const values are opaque in
    // this slice, they do not count as catch-all coverage.
    let source = concat!(
        "pub const LIMIT: I32 = 5
",
        "pub fn tail(x: I32) -> I32 {
",
        "    match x {
",
        "        LIMIT | 6 => 1,
",
        "        _ => 2,
",
        "    }
",
        "}
",
        "pub fn stmt(x: I32) -> I32 {
",
        "    match x {
",
        "        LIMIT => { let hit = 1 },
",
        "        _ => { let hit = 2 },
",
        "    }
",
        "    0
",
        "}
",
    );
    assert_success_result(run_check(source, "", &[], &[]), "wasm32-core", "dev");
}

#[test]
fn imported_const_patterns_in_primitive_match_check() {
    // Direct imports, module-member paths, aliases, and `pub use`
    // re-exports all resolve const patterns to the original const type.
    let root_source = concat!(
        "use acme:empty/values
",
        "use acme:empty/values.{CAP as MAX}
",
        "use acme:empty/reexport.{CAP as REEXPORTED}
",
        "pub fn direct(x: I32) -> I32 {
",
        "    match x {
",
        "        MAX => 1,
",
        "        _ => 2,
",
        "    }
",
        "}
",
        "pub fn member(x: I32) -> I32 {
",
        "    match x {
",
        "        values.CAP => 1,
",
        "        _ => 2,
",
        "    }
",
        "}
",
        "pub fn reexported(x: I32) -> I32 {
",
        "    match x {
",
        "        REEXPORTED | 9 => 1,
",
        "        _ => 2,
",
        "    }
",
        "}
",
    );
    let output = run_check(
        root_source,
        "",
        &[
            (
                "src/values.sai",
                "pub const CAP: I32 = 7
",
            ),
            (
                "src/reexport.sai",
                "pub use acme:empty/values.{CAP}
",
            ),
        ],
        &[],
    );
    assert_success_result(output, "wasm32-core", "dev");
}

#[test]
fn integer_domain_coverage_in_primitive_match_checks() {
    // Literal and range patterns whose union spans the scrutinee type's
    // whole domain are exhaustive without a catch-all (§6.22.2) — in
    // tail, statement, and unit-discard positions alike. Partial coverage
    // still diagnoses NON_EXHAUSTIVE_MATCH.
    let source = concat!(
        "pub fn ranged(x: U8) -> I32 {
",
        "    match x {
",
        "        0..=127 => 1,
",
        "        128..=255 => 2,
",
        "    }
",
        "}
",
        "pub fn open_ended(x: U8) -> I32 {
",
        "    match x {
",
        "        0..=200 => 1,
",
        "        201.. => 2,
",
        "    }
",
        "}
",
        "pub fn negative(x: I8) -> I32 {
",
        "    match x {
",
        "        -128..=127 => 1,
",
        "    }
",
        "}
",
        "pub fn exclusive(x: U8) -> I32 {
",
        "    match x {
",
        "        0..5 => 1,
",
        "        5..=255 => 2,
",
        "    }
",
        "}
",
        "pub fn unit_tail(x: U8) {
",
        "    match x {
",
        "        0..=127 => 1,
",
        "        128..=255 => 2,
",
        "    }
",
        "}
",
    );
    assert_success_result(run_check(source, "", &[], &[]), "wasm32-core", "dev");

    let output = run_check(
        "pub fn partial(x: U8) -> I32 {
    match x {
        0..=100 => 1,
    }
}
",
        "",
        &[],
        &[],
    );
    let stdout = String::from_utf8(output.stdout).expect("CLI stdout is UTF-8");
    assert_eq!(
        output.status.code(),
        Some(1),
        "partial coverage must fail the check:\n{stdout}"
    );
    assert!(
        stdout.contains("\"code\":\"NON_EXHAUSTIVE_MATCH\""),
        "partial coverage must diagnose NON_EXHAUSTIVE_MATCH:\n{stdout}"
    );
}

#[test]
fn const_range_endpoints_in_primitive_match_check() {
    // Scalar const paths can close both ends of a primitive range
    // pattern, including module-member paths. Their values remain opaque
    // to emptiness and exhaustiveness analysis in this slice.
    let root_source = concat!(
        "use acme:empty/values.{HIGH}
",
        "pub const LOW: I32 = 1
",
        "pub fn pick(x: I32) -> I32 {
",
        "    match x {
",
        "        LOW..=HIGH => 1,
",
        "        _ => 2,
",
        "    }
",
        "}
",
        "pub fn stmt(x: I32) -> I32 {
",
        "    match x {
",
        "        LOW..=HIGH => { let inside = 1 },
",
        "        _ => { let inside = 2 },
",
        "    }
",
        "    0
",
        "}
",
    );
    let output = run_check(
        root_source,
        "",
        &[(
            "src/values.sai",
            "pub const HIGH: I32 = 9
",
        )],
        &[],
    );
    assert_success_result(output, "wasm32-core", "dev");
}

#[test]
fn runtime_enum_constructor_arithmetic_is_not_const_evaluated() {
    let source = concat!(
        "enum Payload { Pair(U8, Bool) }
",
        "pub fn make() -> Payload {
",
        "    Payload.Pair(255 + 1, true)
",
        "}
",
    );
    let output = run_check(source, "", &[], &[]);
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert_check_stays_gated(&output, "runtime enum constructor arithmetic");
    assert!(
        !stdout.contains("\"code\":\"CONST_EVAL_PANIC\""),
        "runtime arithmetic must not be evaluated as a const initializer:
{stdout}"
    );
}

#[test]
