#[test]
fn primitive_const_expression_errors_are_checked() {
    for (source, code, message) in [
        (
            "pub const VALUE: I8 = 127 + 1
",
            "CONST_EVAL_PANIC",
            "integer overflow in addition",
        ),
        (
            "pub const VALUE: I32 = 1 / 0
",
            "CONST_EVAL_PANIC",
            "division by zero",
        ),
        (
            "pub const VALUE: U8 = 1 % 0
",
            "CONST_EVAL_PANIC",
            "remainder by zero",
        ),
        (
            "pub const VALUE: I8 = -(-128)
",
            "CONST_EVAL_PANIC",
            "integer overflow in negation",
        ),
        (
            "pub const VALUE: I32 = 1 + true
",
            "TYPE_MISMATCH",
            "expected `I32`, found a Bool literal",
        ),
        (
            "pub const BASE: I8 = 100
pub const VALUE: I8 = BASE + 28
",
            "CONST_EVAL_PANIC",
            "integer overflow in addition",
        ),
        (
            "pub const BASE: I8 = 100
pub const ALIAS: I8 = BASE
pub const VALUE: I8 = ALIAS + 28
",
            "CONST_EVAL_PANIC",
            "integer overflow in addition",
        ),
        (
            "pub const BASE: I8 = 100
pub const OFFSET: I8 = BASE + 27
pub const VALUE: I8 = OFFSET + 1
",
            "CONST_EVAL_PANIC",
            "integer overflow in addition",
        ),
        (
            "pub const TRUTH: Bool = true
pub const VALUE: I32 = TRUTH + 1
",
            "TYPE_MISMATCH",
            "expected `I32`, found `Bool`",
        ),
        (
            "pub const FIRST: I32 = SECOND + 1
pub const SECOND: I32 = FIRST + 1
",
            "CONST_CYCLE",
            "const depends on itself",
        ),
        (
            "pub const LOOP: Bool = LOOP == true
",
            "CONST_CYCLE",
            "const depends on itself",
        ),
        (
            "pub const VALUE: Bool = true + false
",
            "OPERATOR_NOT_SUPPORTED",
            "operator `+` has no `Add` implementation for `Bool`",
        ),
        (
            "pub const VALUE: F64 = 1.0 % 2.0
",
            "OPERATOR_NOT_SUPPORTED",
            "operator `%` has no `Rem` implementation for `F64`",
        ),
        (
            "pub const VALUE: I32 = not false
",
            "TYPE_MISMATCH",
            "expected `I32`, found `Bool`",
        ),
        (
            "pub const VALUE: I32 = true and false
",
            "TYPE_MISMATCH",
            "expected `I32`, found `Bool`",
        ),
        (
            "pub const VALUE: Str = false or true
",
            "TYPE_MISMATCH",
            "expected `Str`, found `Bool`",
        ),
        (
            "pub const VALUE: () = not false
",
            "TYPE_MISMATCH",
            "expected `()`, found `Bool`",
        ),
        (
            "pub const VALUE: I8 = 1 << 8
",
            "CONST_EVAL_PANIC",
            "shift amount out of range",
        ),
        (
            "pub const VALUE: I32 = 1 << true
",
            "TYPE_MISMATCH",
            "expected `U32`, found a Bool literal",
        ),
        (
            "pub const VALUE: Bool = true & false
",
            "OPERATOR_NOT_SUPPORTED",
            "operator `&` has no `BitAnd` implementation for `Bool`",
        ),
        (
            "pub const VALUE: F32 = 1.0 << 1
",
            "OPERATOR_NOT_SUPPORTED",
            "operator `<<` is not defined for `F32`",
        ),
        (
            "pub const VALUE: Byte = b'x' + b'y'
",
            "OPERATOR_NOT_SUPPORTED",
            "operator `+` has no `Add` implementation for `Byte`",
        ),
        (
            "pub const VALUE: Byte = b'x' +% b'y'
",
            "OPERATOR_NOT_SUPPORTED",
            "operator `+%` is not defined for `Byte`",
        ),
        (
            "pub const VALUE: I8 = (127 +% 1) - 1
",
            "CONST_EVAL_PANIC",
            "integer overflow in subtraction",
        ),
        (
            "pub const VALUE: U8 = (0 -% 1) + 1
",
            "CONST_EVAL_PANIC",
            "integer overflow in addition",
        ),
        (
            "pub const VALUE: I8 = (1 << 7) - 1
",
            "CONST_EVAL_PANIC",
            "integer overflow in subtraction",
        ),
        (
            "pub const VALUE: I32 = 1 < 2
",
            "TYPE_MISMATCH",
            "expected `I32`, found `Bool`",
        ),
        (
            "pub const VALUE: Bool = 1 < true
",
            "TYPE_MISMATCH",
            "expected `I64`, found a Bool literal",
        ),
        (
            "pub const VALUE: Bool = 18446744073709551616 < 0
",
            "LITERAL_OUT_OF_RANGE",
            "integer literal is out of range for `I64`",
        ),
        (
            "pub const VALUE: Bool = false and (1 + true == 0)
",
            "TYPE_MISMATCH",
            "expected `I64`, found a Bool literal",
        ),
        (
            "pub const VALUE: Bool = \"a\" == (1 + 2)
",
            "TYPE_MISMATCH",
            "expected `Str`, found `I64`",
        ),
        (
            "pub const VALUE: Bool = () == (1 + 2)
",
            "TYPE_MISMATCH",
            "expected `()`, found `I64`",
        ),
        (
            "pub const VALUE: Bool = \"a\" == (1 < 2)
",
            "TYPE_MISMATCH",
            "expected `Str`, found `Bool`",
        ),
    ] {
        let output = run_check(source, "", &[], &[]);
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert_eq!(output.status.code(), Some(1), "{stdout}");
        assert!(
            stdout.contains(&format!("\"code\":\"{code}\"")) && stdout.contains(message),
            "expected {code} with {message:?}:
{stdout}"
        );
        assert!(
            !stdout.contains("\"code\":\"FEATURE_NOT_IMPLEMENTED\""),
            "supported invalid const expression must not be gated:
{stdout}"
        );
    }
}

#[test]
fn type_mismatched_const_alias_does_not_cascade_const_eval_panic() {
    let source = concat!(
        "pub const BASE: I8 = 100\n",
        "pub const ALIAS: I16 = BASE\n",
        "pub const VALUE: I16 = ALIAS + 32700\n",
    );
    let output = run_check(source, "", &[], &[]);
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert_eq!(output.status.code(), Some(1), "{stdout}");
    assert!(
        stdout.contains("\"code\":\"TYPE_MISMATCH\""),
        "the alias type mismatch remains the primary error:\n{stdout}"
    );
    assert!(
        !stdout.contains("\"code\":\"CONST_EVAL_PANIC\""),
        "an invalid alias must not propagate a value into later const evaluation:\n{stdout}"
    );
}

